create extension if not exists pgcrypto;

-- ============================================================================
-- Profiles (one row per auth user; role lives here, never in user-editable metadata)
-- ============================================================================
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  full_name text,
  display_name text,
  role text not null default 'user' check (role in ('admin', 'user')),
  platform_role text,
  platform_role_name text,
  account_type text,
  country text,
  phone text,
  created_date timestamptz not null default now(),
  updated_date timestamptz not null default now()
);
alter table public.profiles enable row level security;

-- ============================================================================
-- Platform owners: permanent super administrators. They are the only people who
-- can grant or revoke super-admin access, and nobody can demote or delete them.
-- ============================================================================
create or replace function public.app_protected_admins() returns text[]
language sql immutable as $$
  select array['vincentnogue2@gmail.com', 'vincentnogue@yahoo.com']
$$;

-- ============================================================================
-- Helpers used by every policy
-- ============================================================================
create or replace function public.app_is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin')
$$;

create or replace function public.app_email() returns text
language sql stable as $$
  select lower(coalesce(auth.jwt() ->> 'email', ''))
$$;

create or replace function public.app_is_owner() returns boolean
language sql stable as $$
  select public.app_email() = any (public.app_protected_admins())
$$;

-- True when the jsonb value (a string or an array of strings) contains the caller's email.
create or replace function public.app_has_email(v jsonb) returns boolean
language sql stable as $$
  select public.app_email() <> '' and case jsonb_typeof(v)
    when 'string' then lower(v #>> '{}') = public.app_email()
    when 'array' then exists (select 1 from jsonb_array_elements_text(v) e where lower(e) = public.app_email())
    else false
  end
$$;

create policy "profiles_read" on public.profiles for select to authenticated
  using (id = auth.uid() or public.app_is_admin());
create policy "profiles_update" on public.profiles for update to authenticated
  using (id = auth.uid() or public.app_is_admin())
  with check (id = auth.uid() or public.app_is_admin());

-- A signed-in user may edit their own profile but can never grant themselves a role.
create or replace function public.profiles_guard() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.updated_date := now();
  if auth.uid() is not null then
    if not public.app_is_admin() then
      new.role := old.role;
      new.platform_role := old.platform_role;
      new.platform_role_name := old.platform_role_name;
      new.email := old.email;
      new.id := old.id;
    elsif not public.app_is_owner() then
      -- Administrators can manage staff, but only the owners grant or revoke super-admin.
      new.role := old.role;
    end if;
  end if;
  -- Owners are permanent super administrators, whoever (or whatever) tries to change that.
  if lower(old.email) = any (public.app_protected_admins()) then
    new.role := 'admin';
    new.email := old.email;
  end if;
  return new;
end $$;
create trigger profiles_guard before update on public.profiles
  for each row execute function public.profiles_guard();

create or replace function public.profiles_protect_delete() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if lower(old.email) = any (public.app_protected_admins()) then
    raise exception 'This account is a protected platform owner and cannot be deleted.';
  end if;
  return old;
end $$;
create trigger profiles_protect_delete before delete on public.profiles
  for each row execute function public.profiles_protect_delete();

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  -- Only non-privileged fields are read from signup metadata; the role is never taken from it.
  insert into public.profiles (id, email, role, full_name, display_name, account_type, country, phone)
  values (
    new.id,
    lower(new.email),
    case when lower(new.email) = any (public.app_protected_admins()) then 'admin' else 'user' end,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'display_name',
    case when new.raw_user_meta_data ->> 'account_type' in ('individual', 'company')
         then new.raw_user_meta_data ->> 'account_type' end,
    left(new.raw_user_meta_data ->> 'country', 80),
    left(new.raw_user_meta_data ->> 'phone', 40)
  )
  on conflict (id) do nothing;
  return new;
end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- Backfill profiles for users that already exist, and make sure the owners are admins.
insert into public.profiles (id, email)
select id, lower(email) from auth.users
on conflict (id) do nothing;
update public.profiles set role = 'admin' where lower(email) = any (public.app_protected_admins());

-- Run once from the SQL editor to create the first platform administrator:
--   select public.promote_admin('you@example.com');
create or replace function public.promote_admin(p_email text) returns void
language plpgsql security definer set search_path = public as $$
begin
  update public.profiles set role = 'admin' where email = lower(p_email);
  if not found then raise exception 'No account with email %', p_email; end if;
end $$;
revoke all on function public.promote_admin(text) from public, anon, authenticated;

-- ============================================================================
-- Generic record store
-- ============================================================================
create table if not exists public.records (
  id uuid primary key default gen_random_uuid(),
  entity text not null check (entity in ('ApiKey', 'CodEntry', 'ContactMessage', 'Hub', 'Invoice', 'MarketplaceConnection', 'PartnerLogo', 'PaymentMethod', 'PlatformRole', 'Purchase', 'Shipment', 'ShipmentEvent', 'Subscription', 'SupportTicket', 'Surcharge', 'TeamMember', 'Tenant', 'Vehicle', 'WebhookDelivery', 'WebhookEndpoint', 'Zone')),
  data jsonb not null default '{}'::jsonb,
  created_by text,
  created_by_id uuid,
  created_date timestamptz not null default now(),
  updated_date timestamptz not null default now()
);
create index if not exists records_entity_created_idx on public.records (entity, created_date desc);
create index if not exists records_tenant_idx on public.records (entity, (data ->> 'tenant_id'));
create index if not exists records_data_gin on public.records using gin (data jsonb_path_ops);
alter table public.records enable row level security;

create or replace function public.records_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare reserved text[] := array['id','created_date','updated_date','created_by','created_by_id','entity'];
begin
  new.data := coalesce(new.data, '{}'::jsonb) - reserved;
  if tg_op = 'INSERT' then
    if auth.uid() is not null then
      new.created_by_id := auth.uid();
      new.created_by := public.app_email();
    end if;
  else
    new.entity := old.entity;
    new.created_by := old.created_by;
    new.created_by_id := old.created_by_id;
    new.created_date := old.created_date;
    new.updated_date := now();
  end if;
  return new;
end $$;
create trigger records_guard before insert or update on public.records
  for each row execute function public.records_guard();

-- ============================================================================
-- Query engine (Mongo-style filters -> SQL). Runs as the caller, so RLS applies.
-- All values go through quote_literal and all field names are validated.
-- ============================================================================
create or replace function public.app_obj(r public.records) returns jsonb
language sql stable as $$
  select r.data || jsonb_build_object(
    'id', r.id, 'created_date', r.created_date, 'updated_date', r.updated_date,
    'created_by', r.created_by, 'created_by_id', r.created_by_id)
$$;

create or replace function public.app_is_col(k text) returns boolean
language sql immutable as $$
  select k in ('id', 'created_date', 'updated_date', 'created_by', 'created_by_id')
$$;

create or replace function public.app_expr(k text) returns text
language plpgsql immutable as $$
begin
  if k !~ '^[A-Za-z_][A-Za-z0-9_]*(\.[A-Za-z_][A-Za-z0-9_]*)*$' then
    raise exception 'invalid field name: %', k;
  end if;
  if public.app_is_col(k) then return k; end if;
  return format('(data #> %L::text[])', '{' || replace(k, '.', ',') || '}');
end $$;

create or replace function public.app_lit(k text, v jsonb) returns text
language plpgsql immutable as $$
begin
  if k in ('id', 'created_by_id') then return quote_literal(v #>> '{}') || '::uuid'; end if;
  if k in ('created_date', 'updated_date') then return quote_literal(v #>> '{}') || '::timestamptz'; end if;
  if k = 'created_by' then return quote_literal(v #>> '{}'); end if;
  return quote_literal(v::text) || '::jsonb';
end $$;

create or replace function public.app_eq(k text, v jsonb) returns text
language plpgsql immutable as $$
declare e text := public.app_expr(k);
begin
  if v is null or jsonb_typeof(v) = 'null' then
    if public.app_is_col(k) then return e || ' is null'; end if;
    return format('(%s is null or %s = ''null''::jsonb)', e, e);
  end if;
  if public.app_is_col(k) then return format('%s = %s', e, public.app_lit(k, v)); end if;
  return format('coalesce(%s @> %s, false)', e, public.app_lit(k, v));
end $$;

create or replace function public.app_op(k text, op text, v jsonb, whole jsonb) returns text
language plpgsql immutable as $$
declare
  e text := public.app_expr(k);
  items text[] := '{}';
  x jsonb;
  txt text;
begin
  case op
    when '$eq' then return public.app_eq(k, v);
    when '$ne' then return 'not ' || public.app_eq(k, v);
    when '$in', '$nin' then
      if jsonb_typeof(v) <> 'array' then raise exception '% expects an array', op; end if;
      for x in select * from jsonb_array_elements(v) loop
        items := items || public.app_eq(k, x);
      end loop;
      txt := case when array_length(items, 1) is null then 'false' else '(' || array_to_string(items, ' or ') || ')' end;
      return case when op = '$in' then txt else 'not ' || txt end;
    when '$gt' then return format('%s > %s', e, public.app_lit(k, v));
    when '$gte' then return format('%s >= %s', e, public.app_lit(k, v));
    when '$lt' then return format('%s < %s', e, public.app_lit(k, v));
    when '$lte' then return format('%s <= %s', e, public.app_lit(k, v));
    when '$exists' then
      -- A field set to null counts as absent, which is how the app treats it.
      if public.app_is_col(k) then return case when v = 'true'::jsonb then 'true' else 'false' end; end if;
      if v = 'true'::jsonb then return format('(%s is not null and %s <> ''null''::jsonb)', e, e); end if;
      return format('(%s is null or %s = ''null''::jsonb)', e, e);
    when '$regex' then
      txt := case when public.app_is_col(k) then format('%s::text', e) else format('(%s #>> ''{}'')', e) end;
      return format('(%s %s %L)', txt,
        case when coalesce(whole ->> '$options', '') like '%i%' then '~*' else '~' end,
        v #>> '{}');
    when '$options' then return 'true';
    else raise exception 'unsupported operator %', op;
  end case;
end $$;

create or replace function public.app_where(q jsonb) returns text
language plpgsql immutable as $$
declare
  k text; v jsonb; opk text; opv jsonb; item jsonb;
  parts text[] := '{}'; sub text[]; bits text[];
begin
  if q is null or jsonb_typeof(q) <> 'object' or q = '{}'::jsonb then return 'true'; end if;
  for k, v in select * from jsonb_each(q) loop
    if k in ('$or', '$and', '$nor') then
      sub := '{}';
      for item in select * from jsonb_array_elements(v) loop
        sub := sub || public.app_where(item);
      end loop;
      continue when array_length(sub, 1) is null;
      parts := parts || case k
        when '$or' then '(' || array_to_string(sub, ' or ') || ')'
        when '$and' then '(' || array_to_string(sub, ' and ') || ')'
        else 'not (' || array_to_string(sub, ' or ') || ')' end;
    elsif jsonb_typeof(v) = 'object' then
      bits := '{}';
      for opk, opv in select * from jsonb_each(v) loop
        bits := bits || public.app_op(k, opk, opv, v);
      end loop;
      parts := parts || case when array_length(bits, 1) is null then 'true' else '(' || array_to_string(bits, ' and ') || ')' end;
    else
      parts := parts || public.app_op(k, '$eq', v, null);
    end if;
  end loop;
  if array_length(parts, 1) is null then return 'true'; end if;
  return array_to_string(parts, ' and ');
end $$;

create or replace function public.app_order(p_sort text) returns text
language plpgsql immutable as $$
declare part text; field text; dir text; out text[] := '{}';
begin
  if p_sort is null or btrim(p_sort) = '' then return 'created_date desc, id'; end if;
  foreach part in array string_to_array(p_sort, ',') loop
    part := btrim(part);
    continue when part = '';
    dir := case when left(part, 1) = '-' then 'desc' else 'asc' end;
    field := ltrim(part, '-+');
    out := out || (public.app_expr(field) || ' ' || dir || ' nulls last');
  end loop;
  return array_to_string(out, ', ') || ', id';
end $$;

create or replace function public.app_query(
  p_entity text, p_query jsonb default '{}'::jsonb, p_sort text default null,
  p_limit int default 1000, p_skip int default 0
) returns jsonb language plpgsql stable as $$
declare res jsonb;
begin
  execute format(
    'select coalesce(jsonb_agg(public.app_obj(r)), ''[]''::jsonb) from (select * from public.records where entity = %L and (%s) order by %s limit %s offset %s) r',
    p_entity, public.app_where(p_query), public.app_order(p_sort),
    least(greatest(coalesce(p_limit, 1000), 0), 5000), greatest(coalesce(p_skip, 0), 0)
  ) into res;
  return res;
end $$;

create or replace function public.app_count(p_entity text, p_query jsonb default '{}'::jsonb) returns bigint
language plpgsql stable as $$
declare n bigint;
begin
  execute format('select count(*) from public.records where entity = %L and (%s)', p_entity, public.app_where(p_query)) into n;
  return n;
end $$;

-- Aggregate: optional group-by field, optional numeric sums. Rows look like
-- { <group>: value, count: n, sum_<field>: total }.
create or replace function public.app_aggregate(
  p_entity text, p_query jsonb default '{}'::jsonb, p_group_by text default null,
  p_sums text[] default '{}', p_sort text default null, p_limit int default 100
) returns jsonb language plpgsql stable as $$
declare
  sel text[] := '{}'; f text; res jsonb; grp text := ''; ord text;
begin
  if p_group_by is not null then
    if p_group_by !~ '^[A-Za-z_][A-Za-z0-9_]*$' then raise exception 'invalid group field'; end if;
    sel := array_append(sel, format('%s #>> ''{}'' as %I',
      case when public.app_is_col(p_group_by) then format('to_jsonb(%s)', p_group_by) else public.app_expr(p_group_by) end,
      p_group_by));
    grp := ' group by 1';
  end if;
  sel := array_append(sel, 'count(*)::int as count');
  foreach f in array coalesce(p_sums, '{}') loop
    if f !~ '^[A-Za-z_][A-Za-z0-9_]*$' then raise exception 'invalid sum field'; end if;
    sel := array_append(sel, format('coalesce(sum(case when jsonb_typeof(data -> %L) = ''number'' then (data ->> %L)::numeric end), 0) as %I',
      f, f, 'sum_' || f));
  end loop;
  ord := case
    when p_sort is null or btrim(p_sort) = '' then 'count desc'
    when left(p_sort, 1) = '-' then format('%I desc', ltrim(p_sort, '-'))
    else format('%I asc', p_sort) end;
  execute format(
    'select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from (select %s from public.records where entity = %L and (%s)%s order by %s limit %s) t',
    array_to_string(sel, ', '), p_entity, public.app_where(p_query), grp, ord,
    least(greatest(coalesce(p_limit, 100), 1), 1000)
  ) into res;
  return jsonb_build_object('rows', res);
end $$;

create or replace function public.app_get(p_entity text, p_id text) returns jsonb
language plpgsql stable as $$
declare res jsonb;
begin
  select public.app_obj(r) into res from public.records r where r.entity = p_entity and r.id = p_id::uuid;
  return res;
exception when invalid_text_representation then
  return null;
end $$;

create or replace function public.app_create(p_entity text, p_data jsonb) returns jsonb
language plpgsql as $$
declare v_id uuid := gen_random_uuid(); r public.records;
begin
  -- No RETURNING: it would demand a SELECT policy, which write-only endpoints
  -- (the public contact form) deliberately do not grant.
  insert into public.records (id, entity, data) values (v_id, p_entity, coalesce(p_data, '{}'::jsonb));
  select * into r from public.records where id = v_id;
  if not found then return jsonb_build_object('id', v_id); end if;
  return public.app_obj(r);
end $$;

create or replace function public.app_bulk_create(p_entity text, p_rows jsonb) returns jsonb
language plpgsql as $$
declare item jsonb; out jsonb := '[]'::jsonb;
begin
  for item in select * from jsonb_array_elements(coalesce(p_rows, '[]'::jsonb)) loop
    out := out || jsonb_build_array(public.app_create(p_entity, item));
  end loop;
  return out;
end $$;

create or replace function public.app_update(p_entity text, p_id text, p_patch jsonb) returns jsonb
language plpgsql as $$
declare r public.records; n int;
begin
  update public.records
     set data = data || (coalesce(p_patch, '{}'::jsonb) - array['id','created_date','updated_date','created_by','created_by_id','entity'])
   where entity = p_entity and id = p_id::uuid;
  get diagnostics n = row_count;
  if n = 0 then return null; end if;
  select * into r from public.records where id = p_id::uuid;
  if not found then return jsonb_build_object('id', p_id); end if;
  return public.app_obj(r);
exception when invalid_text_representation then
  return null;
end $$;

create or replace function public.app_delete(p_entity text, p_id text) returns boolean
language plpgsql as $$
begin
  delete from public.records where entity = p_entity and id = p_id::uuid;
  return found;
exception when invalid_text_representation then
  return false;
end $$;

-- True when some record the caller may read mentions this file (used to authorise signed URLs).
create or replace function public.app_file_referenced(p_uri text) returns boolean
language sql stable as $$
  select exists (select 1 from public.records where position(p_uri in data::text) > 0)
$$;

-- ============================================================================
-- File storage
-- ============================================================================
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  ('public-files', 'public-files', true, 10485760, array['image/png','image/jpeg','image/webp','image/gif','image/svg+xml']),
  ('private-files', 'private-files', false, 15728640, array['image/png','image/jpeg','image/webp','application/pdf'])
on conflict (id) do update
  set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;

-- Files live under "<user id>/..." so every user can only write inside their own folder.
create policy "public_files_read" on storage.objects for select to anon, authenticated
  using (bucket_id = 'public-files');
create policy "public_files_insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'public-files' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "public_files_delete" on storage.objects for delete to authenticated
  using (bucket_id = 'public-files' and ((storage.foldername(name))[1] = auth.uid()::text or public.app_is_admin()));

create policy "private_files_read" on storage.objects for select to authenticated
  using (bucket_id = 'private-files' and ((storage.foldername(name))[1] = auth.uid()::text or public.app_is_admin()));
create policy "private_files_insert" on storage.objects for insert to authenticated
  with check (bucket_id = 'private-files' and (storage.foldername(name))[1] = auth.uid()::text);
create policy "private_files_delete" on storage.objects for delete to authenticated
  using (bucket_id = 'private-files' and ((storage.foldername(name))[1] = auth.uid()::text or public.app_is_admin()));

-- ============================================================================
-- Bulk updates with array operators ($set, $addToSet, $pull) — used to keep
-- `member_emails` (the access list every policy reads) in step with the team.
-- ============================================================================
create or replace function public.app_update_many(p_entity text, p_query jsonb, p_ops jsonb) returns integer
language plpgsql set search_path = public, pg_temp as $$
declare
  expr text := 'data';
  op text; spec jsonb; f text; v jsonb; n integer;
begin
  for op, spec in select * from jsonb_each(coalesce(p_ops, '{}'::jsonb)) loop
    if op not in ('$set', '$addToSet', '$pull') then
      raise exception 'unsupported update operator %', op;
    end if;
    for f, v in select * from jsonb_each(spec) loop
      if f !~ '^[A-Za-z_][A-Za-z0-9_]*$' then raise exception 'invalid field name: %', f; end if;
      if op = '$set' then
        expr := format('(%s || jsonb_build_object(%L, %L::jsonb))', expr, f, v::text);
      elsif op = '$addToSet' then
        expr := format(
          'jsonb_set(%1$s, %2$L::text[], case when coalesce(%1$s -> %3$L, ''[]''::jsonb) @> jsonb_build_array(%4$L::jsonb) then coalesce(%1$s -> %3$L, ''[]''::jsonb) else coalesce(%1$s -> %3$L, ''[]''::jsonb) || jsonb_build_array(%4$L::jsonb) end, true)',
          expr, '{' || f || '}', f, v::text);
      else
        expr := format(
          'jsonb_set(%1$s, %2$L::text[], coalesce((select jsonb_agg(e) from jsonb_array_elements(coalesce(%1$s -> %3$L, ''[]''::jsonb)) e where e <> %4$L::jsonb), ''[]''::jsonb), true)',
          expr, '{' || f || '}', f, v::text);
      end if;
    end loop;
  end loop;
  execute format('update public.records set data = %s where entity = %L and (%s)', expr, p_entity, public.app_where(p_query));
  get diagnostics n = row_count;
  return n;
end $$;


-- ===== Row-level security, one set of policies per entity =====

-- ApiKey
create policy "ApiKey_read" on public.records for select to authenticated using (entity = 'ApiKey' and (app_has_email(data->'member_emails') OR app_is_admin()));
create policy "ApiKey_create" on public.records for insert to authenticated with check (entity = 'ApiKey' and (app_has_email(data->'member_emails') OR app_is_admin()));
create policy "ApiKey_update" on public.records for update to authenticated using (entity = 'ApiKey' and (app_has_email(data->'member_emails') OR app_is_admin())) with check (entity = 'ApiKey');
create policy "ApiKey_delete" on public.records for delete to authenticated using (entity = 'ApiKey' and (created_by_id = auth.uid() OR app_is_admin()));

-- CodEntry
create policy "CodEntry_read" on public.records for select to authenticated using (entity = 'CodEntry' and (app_has_email(data->'member_emails') OR app_is_admin()));
create policy "CodEntry_create" on public.records for insert to authenticated with check (entity = 'CodEntry' and (app_has_email(data->'member_emails') OR app_is_admin()));
create policy "CodEntry_update" on public.records for update to authenticated using (entity = 'CodEntry' and (app_has_email(data->'member_emails') OR app_is_admin())) with check (entity = 'CodEntry');
create policy "CodEntry_delete" on public.records for delete to authenticated using (entity = 'CodEntry' and (created_by_id = auth.uid() OR app_is_admin()));

-- ContactMessage
